const hoje = new Date();
hoje.setHours(0, 0, 0, 0);
return $input.all().map(({ json: doc }) => {
  const validade = new Date(doc.data_validade);
  const diffDias = Math.round((validade - hoje) / (1000 * 60 * 60 * 24));
  const dataFormatada = validade.toLocaleDateString('pt-BR', { timeZone: 'UTC' });
  let texto;
  if (diffDias < 0) {
    texto = '🚨 Seu documento "' + doc.tipo_documento + '" esta VENCIDO desde ' + dataFormatada + '. Providencie a renovacao o quanto antes.';
  } else if (diffDias === 0) {
    texto = '🚨 Seu documento "' + doc.tipo_documento + '" vence HOJE (' + dataFormatada + '). Providencie a renovacao com urgencia.';
  } else {
    texto = '⚠️ Seu documento "' + doc.tipo_documento + '" vence em ' + diffDias + ' dia(s) (' + dataFormatada + '). Nao esqueca de renovar.';
  }
  return { json: { numero: (doc.whatsapp_numero || '').replace(/\D/g, ''), texto } };
});
